import { ReactNode, FC } from 'react';

type ResultStatus = 'success' | 'error' | 'info' | 'warning' | 'waiting';
interface ResultProps {
    /** 状态类型 */
    status: ResultStatus;
    /** 标题 */
    title: ReactNode;
    /** 描述 */
    description?: ReactNode;
    /** 自定义图标 */
    icon?: ReactNode;
    /** 操作区 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const Result: FC<ResultProps>;

export { Result, Result as default };
export type { ResultProps, ResultStatus };
